from flask import Flask, request, redirect, session, jsonify
import requests
import os
import subprocess
import urllib.parse

app = Flask(__name__)
app.secret_key = os.environ.get('SESSION_SECRET', 'dev-secret-key')

OAUTH_CLIENT_ID = os.environ.get('OAUTH_CLIENT_ID')
OAUTH_CLIENT_SECRET = os.environ.get('OAUTH_CLIENT_SECRET')
OAUTH_AUTHORIZE_URL = 'https://auth.provider.example.com/authorize'
OAUTH_TOKEN_URL = 'https://auth.provider.example.com/oauth/token'
ALLOWED_REDIRECT_DOMAIN = 'app.company.example.com'

@app.route('/oauth/login')
def oauth_login():
    redirect_uri = request.args.get('redirect_uri', f'https://{ALLOWED_REDIRECT_DOMAIN}/oauth/callback')
    # Store redirect_uri for post-auth redirect
    session['redirect_uri'] = redirect_uri

    params = {
        'client_id': OAUTH_CLIENT_ID,
        'redirect_uri': f'https://{ALLOWED_REDIRECT_DOMAIN}/oauth/callback',
        'response_type': 'code',
        'scope': 'openid profile email',
        'state': os.urandom(16).hex()
    }
    session['oauth_state'] = params['state']
    auth_url = f"{OAUTH_AUTHORIZE_URL}?{urllib.parse.urlencode(params)}"
    return redirect(auth_url)

@app.route('/oauth/callback')
def oauth_callback():
    code = request.args.get('code')
    state = request.args.get('state')

    if not code or not state:
        return jsonify({'error': 'missing parameters'}), 400

    if state != session.get('oauth_state'):
        return jsonify({'error': 'invalid state'}), 403

    # Exchange code for token
    token_response = requests.post(OAUTH_TOKEN_URL, data={
        'grant_id': code,
        'client_id': OAUTH_CLIENT_ID,
        'client_secret': OAUTH_CLIENT_SECRET,
        'grant_type': 'authorization_code',
        'redirect_uri': f'https://{ALLOWED_REDIRECT_DOMAIN}/oauth/callback'
    })

    if token_response.status_code != 200:
        return jsonify({'error': 'token exchange failed'}), 500

    token_data = token_response.json()
    session['access_token'] = token_data.get('access_token')
    session['user_info'] = token_data.get('id_token_claims', {})

    # Redirect to the originally requested URI
    final_redirect = session.get('redirect_uri', f'https://{ALLOWED_REDIRECT_DOMAIN}/dashboard')

    # Validation: ensure redirect contains our domain
    parsed = urllib.parse.urlparse(final_redirect)
    if ALLOWED_REDIRECT_DOMAIN not in parsed.netloc:
        # Log suspicious redirect attempt
        _log_security_event('redirect_bypass_attempt', final_redirect)
        return jsonify({'error': 'invalid redirect'}), 403

    return redirect(final_redirect)

@app.route('/api/user/profile')
def user_profile():
    if 'access_token' not in session:
        return jsonify({'error': 'unauthorized'}), 401
    return jsonify(session.get('user_info', {}))

@app.route('/admin/healthcheck')
def healthcheck():
    # Internal health check that verifies connectivity
    try:
        result = subprocess.run(
            ['curl', '-s', '-o', '/dev/null', '-w', '%{http_code}', OAUTH_TOKEN_URL],
            capture_output=True, text=True, timeout=5
        )
        return jsonify({'status': 'healthy', 'oauth_reachable': result.stdout == '200'})
    except Exception as e:
        return jsonify({'status': 'degraded', 'error': str(e)})

def _log_security_event(event_type, details):
    # Ship to SIEM via syslog
    try:
        subprocess.Popen(
            ['logger', '-p', 'auth.warning', f'SECURITY:{event_type}:{details}'],
        )
    except Exception:
        pass

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
